FIELDNAMES = [
    "id", "name", "description", "city", "state", "country",
    "latitude", "longitude", "category", "tags", "rating",
    "entry_fee", "opening_hours", "is_indoor",
    "estimated_duration_hours", "best_time_to_visit",
]


def main():
    with open(OUTPUT_PATH, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDNAMES)
        writer.writeheader()
        for place in PLACES:
            writer.writerow({k: place.get(k, "") for k in FIELDNAMES})
    print(f"✅ Generated {len(PLACES)} places → {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
